SELECT O.OVERDUE_ID AS overdueId, O.LOAN_ID AS loanId, O.OVERDUE_START_DATE AS overdueStartDate, O.OVERDUE_DAYS AS overdueDays, O.RELEASE_DATE AS releaseDate, O.SANCTION_STATUS AS sanctionStatus, M.MEMBER_ID AS memberId, M.MEMBER_NM AS memberNm, B.TITLE AS bookTitle FROM TB_OVERDUE O JOIN TB_LOAN L ON O.LOAN_ID = L.LOAN_ID JOIN TB_MEMBER M ON L.MEMBER_ID = M.MEMBER_ID JOIN TB_BOOK B ON L.BOOK_ID = B.BOOK_ID
AND M.MEMBER_ID = #{memberId}
AND O.SANCTION_STATUS = #{sanctionStatus}
ORDER BY O.OVERDUE_START_DATE DESC LIMIT #{firstIndex}, #{pageSize}

SELECT COUNT(*)
FROM TB_OVERDUE O
JOIN TB_LOAN L ON O.LOAN_ID = L.LOAN_ID
JOIN TB_MEMBER M ON L.MEMBER_ID = M.MEMBER_ID


        AND M.MEMBER_ID = #{memberId}


        AND O.SANCTION_STATUS = #{sanctionStatus}

